12	declare_lint_rule! {
13	    /// Disallow `javascript:` URLs.
14	    ///
15	    /// Using `javascript:` URLs is considered a form of `eval` and can be a security risk.
16	    /// These URLs can execute arbitrary JavaScript code, which can lead to cross-site scripting (XSS) vulnerabilities.
17	    ///
18	    /// ## Examples
19	    ///
20	    /// ### Invalid
21	    ///
22	    /// ```jsx,expect_diagnostic
23	    /// <a href="javascript:void(0)">Click me</a>
24	    /// ```
25	    ///
26	    /// ```jsx,expect_diagnostic
27	    /// <a href="javascript:alert('XSS')">Click me</a>
28	    /// ```
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// React.createElement('a', { href: 'javascript:void(0)' });
32	    /// ```
33	    ///
34	    /// ### Valid
35	    ///
36	    /// ```jsx
37	    /// <a href="https://example.com">Click me</a>
38	    /// ```
39	    ///
40	    /// ```jsx
41	    /// <a href="/path/to/page">Click me</a>
42	    /// ```
43	    ///
44	    /// ```jsx
45	    /// <a href="#section">Click me</a>
46	    /// ```
47	    ///
48	    pub NoScriptUrl {
49	        version: "2.3.9",
50	        name: "noScriptUrl",
51	        language: "js",
52	        sources: &[
53	            RuleSource::Eslint("no-script-url").same(),
54	            // Framework-specific equivalents
55	            RuleSource::EslintReact("jsx-no-script-url").same(),
56	            RuleSource::EslintQwik("jsx-no-script-url").same(),
57	            RuleSource::EslintSolid("jsx-no-script-url").same(),
58	            RuleSource::EslintReactXyz("dom-no-script-url").same(),
59	        ],
60	        recommended: true,
61	        severity: Severity::Error,
62	    }
63	}
