82	impl Rule for NoScriptUrl {
83	    type Query = Semantic<AnyJsElementWithHref>;
84	    type State = NoScriptUrlState;
85	    type Signals = Option<Self::State>;
86	    type Options = NoScriptUrlOptions;
87	
88	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
89	        let node = ctx.query();
90	        let model = ctx.model();
91	
92	        match node {
93	            AnyJsElementWithHref::JsxAttribute(jsx_attribute) => {
94	                // Check if this is an href attribute
95	                let name = jsx_attribute.name().ok()?;
96	                if let AnyJsxAttributeName::JsxName(jsx_name) = name {
97	                    if jsx_name.syntax().text_trimmed() != "href" {
98	                        return None;
99	                    }
100	                } else {
101	                    return None;
102	                }
103	
104	                // Check if the value contains javascript:
105	                let static_value = jsx_attribute.as_static_value()?;
106	                if let Some(const_str) = static_value.as_string_constant()
107	                    && const_str
108	                        .trim()
109	                        .to_lowercase_cow()
110	                        .starts_with("javascript:")
111	                {
112	                    return Some(NoScriptUrlState::JsxAttribute(
113	                        jsx_attribute.initializer()?.range(),
114	                    ));
115	                }
116	            }
117	            AnyJsElementWithHref::JsCallExpression(call_expression) => {
118	                // Check if this is a React.createElement call
119	                if let Some(react_create_element) =
120	                    ReactCreateElementCall::from_call_expression(call_expression, model)
121	                {
122	                    let ReactCreateElementCall { props, .. } = react_create_element;
123	
124	                    // Look for href property in the props object
125	                    if let Some(props) = props {
126	                        let members = props.members();
127	                        for member in members {
128	                            let Ok(member) = member else { continue };
129	                            let Some(property_member) = member.as_js_property_object_member()
130	                            else {
131	                                continue;
132	                            };
133	                            let Ok(property_name) = property_member.name() else {
134	                                continue;
135	                            };
136	                            let Some(name) = property_name.as_js_literal_member_name() else {
137	                                continue;
138	                            };
139	
140	                            if name.syntax().text_trimmed() == "href" {
141	                                let value = property_member.value().ok()?;
142	
143	                                // Check if it's a string literal with javascript:
144	                                if let Some(string_literal) = value.as_any_js_literal_expression()
145	                                    && let Some(string_value) =
146	                                        string_literal.as_js_string_literal_expression()
147	                                {
148	                                    let text = string_value.inner_string_text().ok()?;
149	                                    if text.trim().to_lowercase_cow().starts_with("javascript:") {
150	                                        return Some(NoScriptUrlState::ReactProp(value.range()));
151	                                    }
152	                                }
153	                            }
154	                        }
155	                    }
156	                }
157	            }
158	        }
159	
160	        None
161	    }
162	
163	    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
164	        let diagnostic = RuleDiagnostic::new(
165	            rule_category!(),
166	            state.range(),
167	            markup! {
168	                "Avoid using "<Emphasis>"javascript:"</Emphasis>" URLs, as they can be a security risk."
169	            }
170	            .to_owned(),
171	        )
172	        .note(markup! {
173	            "Using "<Emphasis>"javascript:"</Emphasis>" URLs can lead to security vulnerabilities such as cross-site scripting (XSS)."
174	        })
175	        .note(markup! {
176	            "Consider using regular URLs, or if you need to handle click events, use event handlers instead."
177	        });
178	
179	        Some(diagnostic)
180	    }
181	}
