183	fn is_global_identifier(callee: &AnyJsExpression) -> bool {
184	    // If the call is a direct reference to `parseInt`
185	    if global_identifier(callee).is_some() {
186	        return true;
187	    }
188	
189	    // If the call is a reference on `Number`
190	    let object = match callee {
191	        AnyJsExpression::JsComputedMemberExpression(expression) => expression.object().ok(),
192	        AnyJsExpression::JsStaticMemberExpression(expression) => expression.object().ok(),
193	        _ => return false,
194	    };
195	
196	    object.and_then(|expr| global_identifier(&expr)).is_some()
197	}
