declare_lint_rule! {
    /// Disallow the use of `eval()`-like functions.
    ///
    /// Passing a string as the first argument to `setTimeout`, `setInterval`, or
    /// `setImmediate` behaves like `eval()`: the string is compiled and executed as
    /// JavaScript code. This is a form of implied `eval()` and can lead to security
    /// and performance issues.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setInterval("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("count = 5", 10);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function () {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        sources: &[RuleSource::Eslint("no-implied-eval").same()],
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let model = ctx.model();

        let callee = node.callee().ok()?;

        // Resolve the callee to a global identifier, taking into account access
        // through `window` or `globalThis`.
        let (reference, name) = global_identifier(&callee)?;

        if !matches!(
            name.text(),
            "setTimeout" | "setInterval" | "setImmediate"
        ) {
            return None;
        }

        // Ignore calls where the function is shadowed by a local binding.
        if model.binding(&reference).is_some() {
            return None;
        }

        let first_argument = node.arguments().ok()?.args().iter().next()?.ok()?;
        let AnyJsCallArgument::AnyJsExpression(expression) = first_argument else {
            return None;
        };

        if is_string_expression(&expression) {
            Some(())
        } else {
            None
        }
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Implied eval() is not allowed."
                },
            )
            .note(markup! {
                "Passing strings to functions like setTimeout, setInterval, or setImmediate is a form of implied eval() and can lead to security and performance issues."
            })
            .note(markup! {
                "Use a function instead of a string."
            }),
        )
    }
}

/// Returns `true` if `expression` is a string literal, a template literal
/// without substitutions, or a string concatenation, ignoring any surrounding
/// parentheses.
fn is_string_expression(expression: &AnyJsExpression) -> bool {
    match expression.clone().omit_parentheses() {
        AnyJsExpression::AnyJsLiteralExpression(
            AnyJsLiteralExpression::JsStringLiteralExpression(_),
        ) => true,
        AnyJsExpression::JsTemplateExpression(template) => {
            // A tagged template does not evaluate to a plain string.
            template.tag().is_none()
                && template.elements().into_iter().all(|element| {
                    matches!(element, AnyJsTemplateElement::JsTemplateChunkElement(_))
                })
        }
        AnyJsExpression::JsBinaryExpression(binary) => {
            if binary.operator().ok() != Some(JsBinaryOperator::Plus) {
                return false;
            }
            let Ok(left) = binary.left() else {
                return false;
            };
            let Ok(right) = binary.right() else {
                return false;
            };
            is_string_expression(&left) || is_string_expression(&right)
        }
        _ => false,
    }
}
